def _parse(version):
    """Split a version string into (core_parts, prerelease_ids).

    Build metadata (after '+') is stripped and ignored.
    """
    text = version.strip()
    # Build metadata is ignored entirely for ordering.
    plus = text.find('+')
    if plus != -1:
        text = text[:plus]

    prerelease = None
    if '-' in text:
        text, prerelease = text.split('-', 1)

    core = text.split('.')
    while len(core) < 3:
        core.append('0')

    ids = [] if prerelease in (None, '') else prerelease.split('.')
    return core, ids


def _identifier_key(identifier):
    if identifier.isdigit():
        # Numeric identifiers compare numerically and rank below alphanumeric ones.
        return (0, int(identifier))
    # Alphanumeric identifiers compare in ASCII order and rank above numeric ones.
    return (1, identifier)


def _sort_key(version):
    core, ids = _parse(version)
    major, minor, patch = (int(core[0]), int(core[1]), int(core[2]))
    if ids:
        pre_flag = 0
        pre_ids = tuple(_identifier_key(i) for i in ids)
    else:
        # No pre-release ranks higher than any pre-release for the same core.
        pre_flag = 1
        pre_ids = ()
    return (major, minor, patch, pre_flag, pre_ids)


def sort_versions(vs):
    """Return versions sorted by SemVer 2.0.0 precedence, lowest first.

    The sort is stable, so versions that tie keep their input order.
    """
    return sorted(vs, key=_sort_key)
